  fl_value fl_t591 = fl_nothing(); /* «соединить» */
  FL_TRY(fl_b_soedinit(ctx, fl_list(fl_t590, 3), kompilyator_flang_text_178, &fl_t591, error));
  fl_value fl_t592 = fl_nothing();
  FL_TRY(fl_field_get(ctx, sostoyanie, "номер", &fl_t592, error));
  return kompilyator_flang_s_oshibkoy(ctx, sostoyanie, kompilyator_flang_text_255, fl_t591, fl_t592, mesto, result, error);
