      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_55, fl_t10396, 2, &fl_t10395, error));
      fl_value fl_t10397 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t10395, gotovye, &fl_t10397, error));
      troyki = hvost;
      zanyatye = fl_t10394;
      gotovye = fl_t10397;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
