/* Тело «Шаг постусловий»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_shag_postusloviy_body(fl_ctx *ctx, fl_value postusloviya, fl_value funkciya, fl_value signatura, fl_value gde, fl_value tablicy, fl_value bedy, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(postusloviya)) {
      *result = bedy;
      return FL_OK;
    } else if (fl_chain_cons(postusloviya)) {
      const fl_value golova = fl_chain_head(postusloviya); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(postusloviya); /* хвост «хвост» */
      fl_value fl_t17715 = fl_nothing();
      FL_TRY(kompilyator_flang_proverit_postuslovie(ctx, golova, funkciya, signatura, gde, tablicy, bedy, &fl_t17715, error));
      const fl_value fl_t17716 = funkciya;
      const fl_value fl_t17717 = signatura;
      const fl_value fl_t17718 = gde;
      const fl_value fl_t17719 = tablicy;
      postusloviya = hvost;
      funkciya = fl_t17716;
      signatura = fl_t17717;
      gde = fl_t17718;
      tablicy = fl_t17719;
      bedy = fl_t17715;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Шаг постусловий", error));
      continue;
    } else {
      return fl_match_fail(ctx, postusloviya, error);
    }
  }
}

